examples.template:
MonarchButton(
    text = {{trigger}},
    onClick = {
        step = 0
        open = true
    },
    variant = MonarchButtonVariant.Danger,
)
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = {{title}}, description = {{description}}) {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
            if (step < steps.size) {
                MonarchText(text = "Step ${step + 1} of ${steps.size}", style = MonarchTextStyle.Caption)
                MonarchProgress(progress = (step + 1) / steps.size.toFloat(), size = MonarchProgressSize.Sm)
            }
            MonarchText(
                text = if (step < steps.size) steps[step].label else {{done.title}},
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
                style = MonarchTextStyle.Heading,
            )
            when (step) {
                0 -> {
                    MonarchText(text = {{review.items.0}})
                    MonarchText(text = {{review.items.1}})
                }
                1 -> {
                    MonarchText(text = {{export.description}})
                    MonarchCheckboxRow(checked = exported, onCheckedChange = { exported = it }, label = {{export.label}})
                    if (!exported) MonarchText(text = {{export.blocked}}, style = MonarchTextStyle.Caption)
                }
                2 -> MonarchText(text = {{confirm.content}})
                else -> MonarchText(text = {{done.content}})
            }
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                if (step in 1 until steps.size) {
                    MonarchButton(text = "Back", onClick = { step-- }, variant = MonarchButtonVariant.Ghost)
                } else if (step == 0) {
                    MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Ghost)
                }
                Spacer(Modifier.weight(1f))
                if (step < steps.size) {
                    val last = step == steps.lastIndex
                    MonarchButton(
                        text = if (last) {{confirm.continueLabel}} else "Continue",
                        onClick = { step++ },
                        variant = if (last) MonarchButtonVariant.Danger else MonarchButtonVariant.Primary,
                        enabled = step != 1 || exported,
                    )
                } else {
                    MonarchButton(text = "Close", onClick = { open = false })
                }
            }
        }
    }
}

examples.setupTemplate:
var open by remember { mutableStateOf(true) }
var step by remember { mutableIntStateOf(0) }
var exported by remember { mutableStateOf(false) }
val steps = listOf(
    MonarchStepperStep(id = "review", label = {{review.title}}),
    MonarchStepperStep(id = "export", label = {{export.title}}),
    MonarchStepperStep(id = "confirm", label = {{confirm.title}}),
)

