examples.code:
MonarchButton(
    text = "Close project",
    onClick = {
        step = 0
        open = true
    },
    variant = MonarchButtonVariant.Danger,
)
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = "Close project", description = "Closing removes the project for everyone.") {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
            if (step < steps.size) {
                MonarchText(text = "Step ${step + 1} of ${steps.size}", style = MonarchTextStyle.Caption)
                MonarchProgress(progress = (step + 1) / steps.size.toFloat(), size = MonarchProgressSize.Sm)
            }
            MonarchText(
                text = if (step < steps.size) steps[step].label else "Project closed",
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
                style = MonarchTextStyle.Heading,
            )
            when (step) {
                0 -> {
                    MonarchText(text = "48 tasks are archived")
                    MonarchText(text = "6 people lose access")
                }
                1 -> {
                    MonarchText(text = "Download the tasks and comments before you continue.")
                    MonarchCheckboxRow(checked = exported, onCheckedChange = { exported = it }, label = "I have downloaded a copy, or I do not need one")
                    if (!exported) MonarchText(text = "Tick the box to continue.", style = MonarchTextStyle.Caption)
                }
                2 -> MonarchText(text = "You can reopen it from Archive for 30 days.")
                else -> MonarchText(text = "It is in Archive.")
            }
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                if (step in 1 until steps.size) {
                    MonarchButton(text = "Back", onClick = { step-- }, variant = MonarchButtonVariant.Ghost)
                } else if (step == 0) {
                    MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Ghost)
                }
                Spacer(Modifier.weight(1f))
                if (step < steps.size) {
                    val last = step == steps.lastIndex
                    MonarchButton(
                        text = if (last) "Close project" else "Continue",
                        onClick = { step++ },
                        variant = if (last) MonarchButtonVariant.Danger else MonarchButtonVariant.Primary,
                        enabled = step != 1 || exported,
                    )
                } else {
                    MonarchButton(text = "Close", onClick = { open = false })
                }
            }
        }
    }
}
